// Kriging Interpolation in Pure JavaScript


export const remap = (CValue: number, OldMin: number, OldMax: number, NewMin: number, NewMax: number) => {
    return (((CValue - OldMin) * (NewMax - NewMin)) / (OldMax - OldMin)) + NewMin;
}

class Pixel {
    pos = {}
    value
    constructor(x, y, z = 0) {
      this.pos = { x, y, z };
      this.value = 0;
    }
}
  
export class PixelMap {
    pixels = []
    p0
    p1
    xRes
    yRes
    domain = [0, 255]
    dataTemp = []
    constructor(p0, p1, xRes, yRes) {
      this.p0 = p0;
      this.p1 = p1;
      this.xRes = xRes;
      this.yRes = yRes;
      this.pixels = this.buildGrid();
    }
  
    buildGrid() {
      const pixels = [];
      const xStep = (this.p1[0] - this.p0[0]) / (this.xRes - 1);
      const yStep = (this.p1[1] - this.p0[1]) / (this.yRes - 1);
      for (let j = 0; j < this.yRes; j++) {
        for (let i = 0; i < this.xRes; i++) {
          const x = this.p0[0] + xStep * i;
          const y = this.p0[1] + yStep * j;
          pixels.push(new Pixel(x, y));
        }
      }
      return pixels;
    }
    update(data) {
        this.dataTemp.push(data)
        this.applyKriging(this.dataTemp)
    }
    applyKrigingIDW(trainingPoints) {
        this.dataTemp = trainingPoints
        
        console.log(trainingPoints)
        let min = Number.MAX_VALUE
        let max = Number.MIN_VALUE
        this.pixels.forEach(pixel => {
            let numerator = 0, denominator = 0;
            trainingPoints.forEach(([tx, ty, tval]) => {
                const dist = Math.sqrt((tx - pixel.pos.x) ** 2 + (ty - pixel.pos.y) ** 2);
                const weight = 1 / (dist + 1e-6); // Avoid division by zero
                numerator += weight * tval;
                denominator += weight;
            });
            // console.log({numerator, denominator})
            pixel.value = numerator / denominator;
            if (min > pixel.value) {
                min = pixel.value
            }
            if (max < pixel.value) {
                max = pixel.value
            }
        });
        // console.log({min, max})
    }
    applyKriging(trainingPoints, options = {}) {
        this.dataTemp = trainingPoints

        // Default parameters
        const defaults = {
            variogramModel: 'gaussian',
            nugget: 0.1,
            sill: 1.0,
            range: 100,
            power: 2, // For power model
            maxDistance: Infinity
        };
        const params = { ...defaults, ...options };
    
        // Validate input
        if (!trainingPoints || trainingPoints.length < 3) {
            // throw new Error('At least 3 training points required');
            return
        }
    
        // Cache training points data
        const points = trainingPoints.map(([x, y, val]) => ({ x, y, val }));
    
        // Calculate variogram parameters from data if not provided
        if (!options.sill || !options.range) {
            const variogram = this.estimateVariogram(points);
            params.sill = variogram.sill;
            params.range = variogram.range;
        }
    
        const n = points.length;
        // const distMatrix = new Array(n).map(() => new Array(n));
        // const weightsMatrix = new Array(n).map(() => new Array(n));

        // Pre-compute distance matrix for training points
        // const n = points.length;
        const distMatrix = new Array(n).fill(0).map(() => new Array(n));
        const weightsMatrix = new Array(n).fill(0).map(() => new Array(n));
    
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                const dx = points[i].x - points[j].x;
                const dy = points[i].y - points[j].y;
                distMatrix[i][j] = Math.sqrt(dx * dx + dy * dy);
                weightsMatrix[i][j] = this.variogram(distMatrix[i][j], params);
            }
        }
    
        // Initialize min/max tracking
        let min = Number.MAX_VALUE;
        let max = Number.MIN_VALUE;
    
        // Process each pixel
        this.pixels.forEach(pixel => {
            // Calculate weights for this pixel
            const weights = new Array(n);
            for (let i = 0; i < n; i++) {
                const dx = points[i].x - pixel.pos.x;
                const dy = points[i].y - pixel.pos.y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist > params.maxDistance) {
                    weights[i] = 0;
                    continue;
                }
                weights[i] = this.variogram(dist, params);
            }
    
            // Solve Kriging system
            const krigingWeights = this.solveKrigingSystem(weightsMatrix, weights, n);
    
            // Calculate interpolated value
            let value = 0;
            let weightSum = 0;
            for (let i = 0; i < n; i++) {
                if (krigingWeights[i] !== 0) {
                    value += krigingWeights[i] * points[i].val;
                    weightSum += krigingWeights[i];
                }
            }
    
            // Normalize and store result
            pixel.value = weightSum > 0 ? value / weightSum : 0;
    
            // Update min/max
            min = Math.min(min, pixel.value);
            max = Math.max(max, pixel.value);
        });
    
        console.log({ min, max });
        this.domain = [min, max]
        return { min, max };
    }
    
    // Variogram models
    variogram(distance, params) {
        const { nugget, sill, range, variogramModel, power } = params;
        const h = distance / range;
        // console.log(params,variogramModel)
        switch (variogramModel) {
            case 'spherical':
                if (distance === 0) return nugget;
                return distance <= range
                    ? (nugget + (sill - nugget) * (1.5 * h - 0.5 * h ** 3))
                    : sill;
            case 'exponential':
                return nugget + (sill - nugget) * (1 - Math.exp(-3 * h));
            case 'gaussian':
                return nugget + (sill - nugget) * (1 - Math.exp(-3 * h ** 2));
            case 'power':
                return nugget + (sill - nugget) * (h ** power);
            default:
                throw new Error('Unknown variogram model');
        }
    }
    
    // Estimate variogram parameters from data
    estimateVariogram(points) {
        const distances = [];
        const differences = [];
    
        // Calculate all pairwise distances and differences
        for (let i = 0; i < points.length; i++) {
            for (let j = i + 1; j < points.length; j++) {
                const dx = points[i].x - points[j].x;
                const dy = points[i].y - points[j].y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                const diff = (points[i].val - points[j].val) ** 2;
                distances.push(dist);
                differences.push(diff);
            }
        }
    
        // Simple estimation (can be improved with proper fitting)
        const maxDist = Math.max(...distances);
        const sill = Math.max(...differences) / 2;
        const range = maxDist / 2;
    
        return { sill, range };
    }
    
    // Solve Kriging system using Gaussian elimination
    solveKrigingSystem(weightsMatrix, weights, n) {
        // Create augmented matrix [weightsMatrix | weights]
        const matrix = new Array(n + 1).fill(0).map(() => new Array(n + 2));
        // const matrix = new Array(n + 1).map(() => new Array(n + 2));
        
        // Fill matrix
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                matrix[i][j] = weightsMatrix[i][j];
            }
            matrix[i][n] = 1; // Lagrange multiplier
            matrix[i][n + 1] = weights[i];
        }
        
        // Last row for sum of weights = 1
        for (let j = 0; j < n; j++) {
            matrix[n][j] = 1;
        }
        matrix[n][n] = 0;
        matrix[n][n + 1] = 1;
    
        // Gaussian elimination
        for (let i = 0; i <= n; i++) {
            let pivot = matrix[i][i];
            if (Math.abs(pivot) < 1e-10) {
                // Find non-zero pivot
                for (let k = i + 1; k <= n; k++) {
                    if (Math.abs(matrix[k][i]) > 1e-10) {
                        [matrix[i], matrix[k]] = [matrix[k], matrix[i]];
                        pivot = matrix[i][i];
                        break;
                    }
                }
            }
    
            for (let j = i; j <= n + 1; j++) {
                matrix[i][j] /= pivot;
            }
    
            for (let k = 0; k <= n; k++) {
                if (k !== i) {
                    const factor = matrix[k][i];
                    for (let j = i; j <= n + 1; j++) {
                        matrix[k][j] -= factor * matrix[i][j];
                    }
                }
            }
        }
    
        // Extract weights
        const result = new Array(n);
        for (let i = 0; i < n; i++) {
            result[i] = matrix[i][n + 1];
        }
        return result;
    }
    
    render(ctx: CanvasRenderingContext2D, legend: any) {
        // console.log({legend})
        this.pixels.forEach(pixel => {
            let  c = remap(pixel.value, this.domain[0], this.domain[1], 0, legend.length)
            c = c < 0 ? 0 : c
            c = c > legend.length-1 ? legend.length-1 : c
            // const c = (pixel.value - 90) * 3
            // console.log({c})
            const col = legend[Math.floor(c)]
            // console.log(col)

            if (col){
                ctx.beginPath()
                ctx.arc(pixel.pos.x, pixel.pos.y, 5, 0, Math.PI * 2) 
                ctx.closePath()
                ctx.fillStyle = `rgba(${col[0]}, ${col[1]}, ${col[2]}, 1)`
                ctx.fill()
            } else {
                console.log(col, c, legend.length)
            }
        })
    }
  }
  
